package ru.sedsystem;

import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.scheduling.annotation.Scheduled;

@RestController @RequestMapping("/api")
class Api {
 private final JdbcTemplate db;
 Api(JdbcTemplate db){this.db=db;}
 private void role(Authentication a,String... roles){if(Arrays.stream(roles).noneMatch(r->a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_"+r)))) throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Недостаточно прав");}
 private boolean is(Authentication a,String role){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_"+role));}
 private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
 private String value(Map<String,Object> b,String k){String v=Objects.toString(b.get(k),"").trim();if(v.isBlank()||v.length()>4000)throw bad("Заполните поле: "+k);return v;}
 private String optional(Map<String,Object>b,String k){String v=Objects.toString(b.get(k),"").trim();if(v.length()>4000)throw bad("Слишком длинное значение: "+k);return v;}
 private long id(Map<String,Object>b,String k){try{return Long.parseLong(value(b,k));}catch(NumberFormatException e){throw bad("Некорректный идентификатор: "+k);}}
 private BigDecimal money(Map<String,Object>b,String k){try{BigDecimal v=new BigDecimal(value(b,k));if(v.signum()<=0||v.scale()>2||v.precision()>15)throw bad("Сумма должна быть положительной, до двух знаков после запятой");return v;}catch(NumberFormatException e){throw bad("Некорректная сумма");}}
 private LocalDate date(Map<String,Object>b,String k){try{return LocalDate.parse(value(b,k));}catch(Exception e){throw bad("Некорректная дата: "+k);}}
 private Map<String,Object> one(String table,long id){var rows=db.queryForList("SELECT * FROM "+table+" WHERE id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Запись не найдена");return rows.get(0);}
 private Map<String,Object> locked(String table,long id){var rows=db.queryForList("SELECT * FROM "+table+" WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Запись не найдена");return rows.get(0);}
 private void state(Map<String,Object> row,String... allowed){if(Arrays.stream(allowed).noneMatch(s->s.equals(row.get("status"))))throw new ResponseStatusException(HttpStatus.CONFLICT,"Действие недоступно в текущем состоянии");}
 private void notify(String user,String msg){db.update("INSERT INTO notifications(recipient,message) VALUES (?,?)",user,msg);}
 @GetMapping("/me") Object me(Authentication a){return Map.of("username",a.getName(),"role",a.getAuthorities().iterator().next().getAuthority().substring(5));}
 @GetMapping("/notifications") Object notifications(Authentication a){return db.queryForList("SELECT * FROM notifications WHERE recipient=? ORDER BY id DESC",a.getName());}
 @GetMapping("/requests") Object requests(Authentication a){role(a,"INITIATOR","BUYER","MANAGER","CONTRACTOR");return is(a,"INITIATOR")?db.queryForList("SELECT * FROM purchase_requests WHERE initiator=? ORDER BY id DESC",a.getName()):db.queryForList("SELECT * FROM purchase_requests ORDER BY id DESC");}
 @PostMapping("/requests") Object createRequest(Authentication a,@RequestBody Map<String,Object>b){role(a,"INITIATOR");db.update("INSERT INTO purchase_requests(initiator,subject,description,amount,due_date,status) VALUES (?,?,?,?,?,'DRAFT')",a.getName(),value(b,"subject"),value(b,"description"),money(b,"amount"),date(b,"dueDate"));return Map.of("ok",true);}
 @PutMapping("/requests/{id}") @Transactional Object editRequest(Authentication a,@PathVariable long id,@RequestBody Map<String,Object>b){role(a,"INITIATOR");var r=locked("purchase_requests",id);if(!a.getName().equals(r.get("initiator")))throw new ResponseStatusException(HttpStatus.FORBIDDEN);state(r,"DRAFT","REVISION","REVIEW","APPROVED");if(!db.queryForList("SELECT id FROM procedures WHERE request_id=?",id).isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"По заявке уже создана закупка");db.update("UPDATE purchase_requests SET subject=?,description=?,amount=?,due_date=?,status='DRAFT',comment=NULL WHERE id=?",value(b,"subject"),value(b,"description"),money(b,"amount"),date(b,"dueDate"),id);return Map.of("ok",true);}
 @PostMapping("/requests/{id}/{action}") @Transactional Object requestAction(Authentication a,@PathVariable long id,@PathVariable String action,@RequestBody(required=false) Map<String,Object> body){var b=body==null?Map.<String,Object>of():body;var r=locked("purchase_requests",id);switch(action){case "submit" -> {role(a,"INITIATOR");if(!a.getName().equals(r.get("initiator")))throw new ResponseStatusException(HttpStatus.FORBIDDEN);state(r,"DRAFT","REVISION");db.update("UPDATE purchase_requests SET status='REVIEW',comment=NULL WHERE id=?",id);}case "approve" -> {role(a,"MANAGER");state(r,"REVIEW");db.update("UPDATE purchase_requests SET status='APPROVED',comment=? WHERE id=?",optional(b,"comment"),id);}case "return" -> {role(a,"MANAGER");state(r,"REVIEW");db.update("UPDATE purchase_requests SET status='REVISION',comment=? WHERE id=?",value(b,"comment"),id);}default -> throw bad("Неизвестное действие");}return Map.of("ok",true);}
 @GetMapping("/procedures") Object procedures(Authentication a){return db.queryForList("SELECT p.*, r.subject, r.amount AS request_amount FROM procedures p JOIN purchase_requests r ON r.id=p.request_id ORDER BY p.id DESC");}
 @PostMapping("/procedures") @Transactional Object createProcedure(Authentication a,@RequestBody Map<String,Object>b){role(a,"BUYER");long rid=id(b,"requestId");var r=locked("purchase_requests",rid);state(r,"APPROVED");if(!db.queryForList("SELECT id FROM procedures WHERE request_id=?",rid).isEmpty())throw bad("По заявке уже создана процедура");db.update("INSERT INTO procedures(request_id,title,conditions,deadline,status) VALUES (?,?,?,?,'OPEN')",rid,value(b,"title"),value(b,"conditions"),date(b,"deadline"));return Map.of("ok",true);}
 @PutMapping("/procedures/{id}") @Transactional Object editProcedure(Authentication a,@PathVariable long id,@RequestBody Map<String,Object>b){role(a,"BUYER");var p=locked("procedures",id);state(p,"OPEN");String title=value(b,"title"),conditions=value(b,"conditions");LocalDate deadline=date(b,"deadline");if(deadline.isBefore(LocalDate.now()))throw bad("Срок подачи не может быть в прошлом");boolean substantive=!title.equals(p.get("title"))||!conditions.equals(p.get("conditions"));db.update("UPDATE procedures SET title=?,conditions=?,deadline=? WHERE id=?",title,conditions,deadline,id);if(substantive){var suppliers=db.queryForList("SELECT DISTINCT supplier FROM offers WHERE procedure_id=?",id);db.update("UPDATE offers SET status='UNDER_REVIEW',review_state=NULL,comment=NULL,clarification_deadline=NULL WHERE procedure_id=?",id);for(var supplier:suppliers)notify((String)supplier.get("supplier"),"Условия процедуры №"+id+" изменены; предложение будет рассмотрено повторно");}else if(!deadline.equals(((java.sql.Date)p.get("deadline")).toLocalDate())){for(var supplier:db.queryForList("SELECT DISTINCT supplier FROM offers WHERE procedure_id=?",id))notify((String)supplier.get("supplier"),"Изменён срок подачи предложений по процедуре №"+id);}return Map.of("ok",true);}
 @GetMapping("/offers") Object offers(Authentication a){role(a,"BUYER","MANAGER","SUPPLIER","CONTRACTOR");String q="SELECT o.*, p.title AS procedure_title FROM offers o JOIN procedures p ON p.id=o.procedure_id ";return is(a,"SUPPLIER")?db.queryForList(q+"WHERE o.supplier=? ORDER BY o.id DESC",a.getName()):db.queryForList(q+"ORDER BY o.id DESC");}
 @PostMapping("/offers") @Transactional Object createOffer(Authentication a,@RequestBody Map<String,Object>b){role(a,"SUPPLIER");long pid=id(b,"procedureId");var p=locked("procedures",pid);state(p,"OPEN");if(((java.sql.Date)p.get("deadline")).toLocalDate().isBefore(LocalDate.now()))throw bad("Срок подачи предложений истёк");if(!db.queryForList("SELECT id FROM offers WHERE procedure_id=? AND supplier=?",pid,a.getName()).isEmpty())throw bad("Предложение уже подано");db.update("INSERT INTO offers(procedure_id,supplier,price,terms,status) VALUES (?,?,?,?,'UNDER_REVIEW')",pid,a.getName(),money(b,"price"),value(b,"terms"));return Map.of("ok",true);}
 @PutMapping("/offers/{id}") @Transactional Object editOffer(Authentication a,@PathVariable long id,@RequestBody Map<String,Object>b){role(a,"SUPPLIER");var initial=one("offers",id);if(!a.getName().equals(initial.get("supplier")))throw new ResponseStatusException(HttpStatus.FORBIDDEN);long procedureId=((Number)initial.get("procedure_id")).longValue();var p=locked("procedures",procedureId);state(p,"OPEN");if(((java.sql.Date)p.get("deadline")).toLocalDate().isBefore(LocalDate.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Срок подачи предложений истёк");var offer=locked("offers",id);if(!a.getName().equals(offer.get("supplier")))throw new ResponseStatusException(HttpStatus.FORBIDDEN);db.update("UPDATE offers SET price=?,terms=?,status='UNDER_REVIEW',review_state=NULL,comment=NULL,clarification_deadline=NULL WHERE id=?",money(b,"price"),value(b,"terms"),id);return Map.of("ok",true);}
 @PostMapping("/offers/{id}/{action}") @Transactional Object offerAction(Authentication a,@PathVariable long id,@PathVariable String action,@RequestBody(required=false) Map<String,Object> body){var b=body==null?Map.<String,Object>of():body;var o=locked("offers",id);String supplier=(String)o.get("supplier");switch(action){
 case "clarify" -> {role(a,"BUYER");state(o,"UNDER_REVIEW");if("PENDING".equals(o.get("review_state")))throw bad("Решение уже на согласовании");String comment=value(b,"comment");db.update("UPDATE offers SET status='NEED_INFO',comment=?,clarification_deadline=CURRENT_TIMESTAMP + INTERVAL '5 days',review_state=NULL WHERE id=?",comment,id);notify(supplier,"По предложению №"+id+" запрошено уточнение: "+comment);}
 case "respond" -> {role(a,"SUPPLIER");if(!supplier.equals(a.getName()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);state(o,"NEED_INFO");if(((java.sql.Timestamp)o.get("clarification_deadline")).toLocalDateTime().isBefore(LocalDateTime.now()))throw bad("Срок уточнения истёк");db.update("UPDATE offers SET status='UNDER_REVIEW',terms=?,price=?,clarification_deadline=NULL WHERE id=?",value(b,"terms"),money(b,"price"),id);}
 case "reject" -> {role(a,"BUYER");state(o,"UNDER_REVIEW");if("PENDING".equals(o.get("review_state")))throw bad("Решение уже на согласовании");String comment=value(b,"comment");db.update("UPDATE offers SET status='REJECTED',comment=? WHERE id=?",comment,id);notify(supplier,"Предложение №"+id+" отклонено: "+comment);}
 case "submit" -> {role(a,"BUYER");state(o,"UNDER_REVIEW");if("PENDING".equals(o.get("review_state")))throw bad("Решение уже на согласовании");db.update("UPDATE offers SET review_state='PENDING',comment=? WHERE id=?",optional(b,"comment"),id);}
 case "approve" -> {role(a,"MANAGER");state(o,"UNDER_REVIEW");if(!"PENDING".equals(o.get("review_state")))throw bad("Решение не направлено на согласование");db.update("UPDATE offers SET status='ACCEPTED',review_state='APPROVED',comment=? WHERE id=?",optional(b,"comment"),id);notify(supplier,"Предложение №"+id+" допущено к участию");}
 case "return" -> {role(a,"MANAGER");state(o,"UNDER_REVIEW");if(!"PENDING".equals(o.get("review_state")))throw bad("Решение не направлено на согласование");db.update("UPDATE offers SET review_state='RETURNED',comment=? WHERE id=?",value(b,"comment"),id);}
 default -> throw bad("Неизвестное действие");}return Map.of("ok",true);}
 @Scheduled(fixedDelay=60000) @Transactional public void closeExpired(){var expired=db.queryForList("SELECT id,supplier FROM offers WHERE status='NEED_INFO' AND clarification_deadline<=CURRENT_TIMESTAMP FOR UPDATE");for(var o:expired){db.update("UPDATE offers SET status='CLOSED_NO_REPLY' WHERE id=?",o.get("id"));notify((String)o.get("supplier"),"Предложение №"+o.get("id")+" закрыто без ответа");}}
 @GetMapping("/results") Object results(Authentication a){role(a,"BUYER","MANAGER","CONTRACTOR");return db.queryForList("SELECT r.*,p.title,o.supplier,o.price FROM results r JOIN procedures p ON p.id=r.procedure_id LEFT JOIN offers o ON o.id=r.offer_id ORDER BY r.id DESC");}
 @PostMapping("/procedures/{id}/result") @Transactional Object result(Authentication a,@PathVariable long id,@RequestBody Map<String,Object>b){role(a,"BUYER");var p=locked("procedures",id);state(p,"OPEN");var pending=db.queryForObject("SELECT COUNT(*) FROM offers WHERE procedure_id=? AND status IN ('UNDER_REVIEW','NEED_INFO')",Integer.class,id);if(pending!=null&&pending>0)throw bad("Сначала завершите рассмотрение всех предложений");String outcome=value(b,"outcome");Long offer=null;if(outcome.equals("WINNER")){offer=id(b,"offerId");var o=one("offers",offer);if(((Number)o.get("procedure_id")).longValue()!=id||!"ACCEPTED".equals(o.get("status")))throw bad("Выберите допущенное предложение этой процедуры");}else if(!outcome.equals("NO_WINNER"))throw bad("Некорректный результат");db.update("INSERT INTO results(procedure_id,offer_id,outcome,comment) VALUES (?,?,?,?)",id,offer,outcome,optional(b,"comment"));db.update("UPDATE procedures SET status='COMPLETED' WHERE id=?",id);return Map.of("ok",true);}
 @GetMapping("/contracts") Object contracts(Authentication a){role(a,"CONTRACTOR","MANAGER","BUYER","INITIATOR");return db.queryForList("SELECT c.*,o.supplier, p.title AS procedure_title FROM contracts c JOIN results r ON r.id=c.result_id JOIN offers o ON o.id=r.offer_id JOIN procedures p ON p.id=r.procedure_id ORDER BY c.id DESC");}
 @PostMapping("/contracts") @Transactional Object createContract(Authentication a,@RequestBody Map<String,Object>b){role(a,"CONTRACTOR");long rid=id(b,"resultId");var r=locked("results",rid);if(!"WINNER".equals(r.get("outcome")))throw bad("Договор создаётся только по результату с победителем");if(!db.queryForList("SELECT id FROM contracts WHERE result_id=?",rid).isEmpty())throw bad("Договор уже создан");LocalDate start=date(b,"startDate"),end=date(b,"endDate");if(end.isBefore(start))throw bad("Дата окончания раньше даты начала");db.update("INSERT INTO contracts(result_id,number,subject,amount,start_date,end_date,status) VALUES (?,?,?,?,?,?,'DRAFT')",rid,value(b,"number"),value(b,"subject"),money(b,"amount"),start,end);return Map.of("ok",true);}
 @PutMapping("/contracts/{id}") @Transactional Object editContract(Authentication a,@PathVariable long id,@RequestBody Map<String,Object>b){role(a,"CONTRACTOR");var c=locked("contracts",id);state(c,"DRAFT","REVISION");LocalDate start=date(b,"startDate"),end=date(b,"endDate");if(end.isBefore(start))throw bad("Дата окончания раньше даты начала");db.update("UPDATE contracts SET number=?,subject=?,amount=?,start_date=?,end_date=? WHERE id=?",value(b,"number"),value(b,"subject"),money(b,"amount"),start,end,id);return Map.of("ok",true);}
 @GetMapping("/contracts/{id}/documents") Object documents(Authentication a,@PathVariable long id){role(a,"CONTRACTOR","MANAGER","BUYER","INITIATOR");return db.queryForList("SELECT id,contract_id,version,filename,content_type FROM contract_documents WHERE contract_id=? ORDER BY version DESC",id);}
 @PostMapping("/contracts/{id}/documents") @Transactional Object upload(Authentication a,@PathVariable long id,@RequestParam("file") MultipartFile file) throws Exception {role(a,"CONTRACTOR");var c=locked("contracts",id);state(c,"DRAFT","REVISION");if(file.isEmpty()||file.getSize()>10_000_000)throw bad("Выберите файл размером до 10 МБ");String name=Objects.toString(file.getOriginalFilename(),"document").replaceAll("[\\\\/\\r\\n]","_");if(name.length()>255)throw bad("Слишком длинное имя файла");Integer v=db.queryForObject("SELECT COALESCE(MAX(version),0)+1 FROM contract_documents WHERE contract_id=?",Integer.class,id);db.update("INSERT INTO contract_documents(contract_id,version,filename,content_type,content) VALUES (?,?,?,?,?)",id,v,name,"application/octet-stream",file.getBytes());return Map.of("ok",true);}
 @GetMapping("/documents/{id}") ResponseEntity<byte[]> download(Authentication a,@PathVariable long id){role(a,"CONTRACTOR","MANAGER","BUYER","INITIATOR");var d=one("contract_documents",id);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename((String)d.get("filename"),java.nio.charset.StandardCharsets.UTF_8).build().toString()).body((byte[])d.get("content"));}
 @GetMapping("/contracts/{id}/approvals") Object approvals(Authentication a,@PathVariable long id){role(a,"CONTRACTOR","MANAGER","BUYER","INITIATOR");return db.queryForList("SELECT a.*,d.version FROM approvals a JOIN contract_documents d ON d.id=a.document_id WHERE a.contract_id=? ORDER BY a.id DESC",id);}
 @PostMapping("/contracts/{id}/{action}") @Transactional Object contractAction(Authentication a,@PathVariable long id,@PathVariable String action,@RequestBody(required=false) Map<String,Object> body){var b=body==null?Map.<String,Object>of():body;var c=locked("contracts",id);switch(action){
 case "submit" -> {role(a,"CONTRACTOR");state(c,"DRAFT","REVISION");if(db.queryForList("SELECT id FROM contract_documents WHERE contract_id=?",id).isEmpty())throw bad("Сначала загрузите документ договора");db.update("UPDATE contracts SET status='REVIEW',comment=NULL WHERE id=?",id);}
 case "approve", "return" -> {role(a,"MANAGER");state(c,"REVIEW");String comment=action.equals("return")?value(b,"comment"):optional(b,"comment");Long document=db.queryForObject("SELECT id FROM contract_documents WHERE contract_id=? ORDER BY version DESC LIMIT 1",Long.class,id);db.update("INSERT INTO approvals(contract_id,document_id,actor,decision,comment) VALUES (?,?,?,?,?)",id,document,a.getName(),action.equals("approve")?"APPROVED":"REVISION",comment);db.update("UPDATE contracts SET status=?,comment=? WHERE id=?",action.equals("approve")?"APPROVED":"REVISION",comment,id);}
 case "edo" -> {role(a,"CONTRACTOR");state(c,"APPROVED");if(c.get("edo_reference")!=null)throw bad("Передача уже зарегистрирована");db.update("UPDATE contracts SET edo_status='SIMULATED',edo_reference=?,edo_at=CURRENT_TIMESTAMP WHERE id=?","DEMO-"+UUID.randomUUID(),id);}
 case "conclude" -> {role(a,"CONTRACTOR");state(c,"APPROVED");if(c.get("edo_reference")==null)throw bad("Сначала выполните демонстрационную передачу в ЭДО");db.update("UPDATE contracts SET status='ACTIVE' WHERE id=?",id);}
 case "execution" -> {role(a,"CONTRACTOR");state(c,"ACTIVE");db.update("UPDATE contracts SET execution_notes=? WHERE id=?",value(b,"notes"),id);}
 case "close" -> {role(a,"CONTRACTOR");state(c,"ACTIVE");if(c.get("execution_notes")==null||c.get("execution_notes").toString().isBlank())throw bad("Сначала внесите сведения об исполнении");db.update("UPDATE contracts SET status='CLOSED' WHERE id=?",id);}
 default -> throw bad("Неизвестное действие");}return Map.of("ok",true);}
}
